"""
Streaming sliding window statistical calculations using Welford's algorithm.
"""
import math
from collections import deque
from typing import Optional, Tuple

class SlidingWindowStats:
    """
    Maintains rolling count, mean, and variance over a sliding temporal/count window.
    """
    def __init__(self, window_size: int = 100):
        if window_size < 2:
            raise ValueError("Window size must be at least 2")
        self.window_size = window_size
        self.values = deque(maxlen=window_size)

    def add(self, value: float) -> None:
        """Add a new sample observation into the window."""
        self.values.append(float(value))

    @property
    def count(self) -> int:
        return len(self.values)

    @property
    def mean(self) -> Optional[float]:
        if not self.values:
            return None
        return sum(self.values) / len(self.values)

    @property
    def std_dev(self) -> Optional[float]:
        if len(self.values) < 2:
            return None
        avg = self.mean
        variance = sum((x - avg) ** 2 for x in self.values) / (len(self.values) - 1)
        return math.sqrt(variance)

    def z_score(self, value: float) -> Optional[float]:
        """Compute standard score for an incoming value relative to window."""
        avg = self.mean
        std = self.std_dev
        if avg is None or std is None or std == 0.0:
            return None
        return (value - avg) / std

"""
Network retry policy with full jitter exponential backoff.
"""
import random
import time
from typing import Callable, TypeVar, Any

T = TypeVar('T')

class BackoffPolicy:
    """
    Computes delay intervals using full jitter exponential backoff.
    """
    def __init__(self, base_delay: float = 0.1, max_delay: float = 5.0, factor: float = 2.0):
        self.base_delay = base_delay
        self.max_delay = max_delay
        self.factor = factor

    def compute_delay(self, attempt: int) -> float:
        """Computes randomized jittered delay for a given retry attempt index."""
        calculated = min(self.max_delay, self.base_delay * (self.factor ** attempt))
        return random.uniform(0, calculated)

    def execute(self, func: Callable[[], T], max_attempts: int = 3) -> T:
        """Executes a callable with automatic retries on Exception."""
        for attempt in range(max_attempts):
            try:
                return func()
            except Exception as e:
                if attempt == max_attempts - 1:
                    raise e
                delay = self.compute_delay(attempt)
                time.sleep(delay)
        raise RuntimeError("Exceeded maximum retry attempts")
